// Stipulate mod: the shared state contract between the core (hooks/core) and the
// interface (hooks/ui). Every value lives under PluginState['stipulate'].

/** Lifecycle phases a change records in state.json. */
export type StipPhase = 'exploring' | 'draft' | 'approved' | 'applying' | 'checked' | 'documented' | 'archived'

/** Worker statuses as the engine registry records them. */
export type StipJobStatus = 'queued' | 'starting' | 'running' | 'waiting' | 'unknown' | 'correction' | 'returned' | 'failed' | 'cancelled'

export type StipAcceptance = 'pending' | 'accepted' | 'rejected'

/** Apply gate mode for main-session edits while the bound change is not approved. */
export type StipApplyGate = 'off' | 'warn' | 'block'

/** One worker attempt as the snapshot shows it (registry job plus live observation). */
export type StipWorker = {
  changeId: string
  taskId: string
  attempt: number
  role: string
  phase: string
  status: StipJobStatus
  acceptance: StipAcceptance
  /** The Claude Code agent id (registry session_id); null before launch is confirmed. */
  agentId: string | null
  lastTool: string | null
  /** Epoch milliseconds; null when unknown. */
  startedAt: number | null
  finishedAt: number | null
  /** Elapsed time at refresh, in milliseconds. */
  elapsedMs: number | null
  hasResult: boolean
  isolated: boolean
  integrated: boolean
  model: string | null
  error: string | null
  reviewReason: string | null
}

/** One task of the approved execution plan with its latest attempt. */
export type StipTask = {
  id: string
  role: string
  phase: string
  objective: string
  criteria: string[]
  dependsOn: string[]
  writePaths: string[]
  ready: boolean
  awaitingReview: boolean
  awaitingIntegration: boolean
  latest: StipWorker | null
}

/** A read-only research helper. */
export type StipHelper = {
  helperId: string
  changeId: string | null
  role: string
  phase: string
  question: string
  status: StipJobStatus
  agentId: string | null
  hasResult: boolean
  startedAt: number | null
  finishedAt: number | null
  error: string | null
  /** A 2-5 word label: the coordinator's `title`, else a model label, else a heuristic one. */
  title: string
  titleSource: StipTitleSource
}

/** Where a display label comes from: given explicitly, generated by a model, or the heuristic fallback. */
export type StipTitleSource = 'explicit' | 'model' | 'fallback'

/** An acceptance criterion of the bound change (spec.md) with its evidence (evidence.md). */
export type StipCriterion = {
  id: string
  /** A 2-5 word label (model-generated, cached; heuristic until ready). */
  title: string
  titleSource: StipTitleSource
  /** The full text, including continuation lines and nested list items. */
  text: string
  evidence?: string
  status: 'passed' | 'failed' | 'unverified' | 'pending'
}

/**
 * A non-archived change of the project, for the change picker. `approval` is exact for the bound
 * change ('approved' | 'stale' | 'none'); for the others it reports whether an approval is recorded
 * ('recorded' | 'none'), without recomputing the contract digest.
 */
export type StipChangeRef = {
  id: string
  phase: string
  /** The proposal's first heading, else the id. */
  title: string
  approval: 'approved' | 'stale' | 'recorded' | 'none'
  /** Active worker jobs (starting, running, waiting, unknown). */
  activeWorkers: number
  /** True while workers are active. */
  inFlight: boolean
  /** True once the change is documented (only archive remains). */
  finished: boolean
  bound: boolean
}

/** A worker attempt whose registry record was changed outside Stip (restored by the integrity watch). */
export type StipTamper = {
  changeId: string
  taskId: string
  attempt: number
  /** The tampered record claimed the attempt was integrated into the main checkout. */
  integratedClaim: boolean
  /** Paths under the task's write_paths that differ from HEAD in the main checkout (git status). */
  paths: string[]
  at: number
  note: string
}

/** One rebase of the worker registry onto a re-approved contract (`registry.rebases[]`). */
export type StipRebase = {
  from: string | null
  to: string
  at: string
  reason: string | null
  /** Tasks whose accepted work was kept. */
  kept: string[]
  /** Tasks reopened (changed, or depending on a changed task): to redelegate. */
  reopened: string[]
  /** Tasks removed from the plan; their jobs moved to `retired_jobs`. */
  retired: string[]
}

/** What `refresh($)` computes for the bound change. */
export type StipSnapshot = {
  /** The bound change id, or null when nothing is bound. */
  changeId: string | null
  phase: StipPhase | null
  schemaVersion: number | null
  /**
   * `current`: the engine approval is current AND is the one the person gave through Stip.
   * `adopted`: that approval predates the mod and was adopted on first activation ("approved (adopted)").
   */
  approval: { current: boolean; digest: string | null; by: string | null; adopted: boolean }
  /** The engine records a current approval the person did not give through Stip (treated as unapproved). */
  approvalUnconfirmed: boolean
  /**
   * False when the worker registry is still tied to a previously approved contract (after a revised
   * contract was re-approved while workers were active): dispatch is refused until it is rebased.
   * The pane offers "Rebase registry" (`stip-action` `{ action: 'rebase', change_id }`).
   */
  registryCurrent: boolean
  /** Tasks with worker records that the approved plan no longer has (retired by the next rebase). */
  orphanTasks: string[]
  /** The registry's most recent rebase, or null. */
  lastRebase: StipRebase | null
  /** Attempts of this change whose registry record was tampered with; inspect `git diff` before accepting. */
  tampered: StipTamper[]
  extensions: string[]
  tasks: StipTask[]
  workers: StipWorker[]
  helpers: StipHelper[]
  ready: string[]
  awaitingReview: string[]
  awaitingIntegration: string[]
  active: { change: number; helpers: number; total: number; writers: number }
  limits: { max_workers: number; max_shared_writers: number }
  /** Non-archived changes in the project. */
  changes: StipChangeRef[]
  /** How many changes are archived. */
  archivedCount: number
  /** Acceptance criteria of the bound change. */
  criteria: StipCriterion[]
  error: string | null
  refreshedAt: number
}

/** A worker profile in orchestration.clients["claude-code"]. */
export type StipProfile = {
  /** 'inherit', an alias (haiku, sonnet, opus, fable) or a full model id. */
  model?: string
  /** 'inherit' | 'low' | 'medium' | 'high' | 'xhigh' | 'max'. */
  effort?: string
  /** An existing agent type to run the worker as (model applies, effort cannot). */
  agent?: string
  /** Run writing tasks in their own git worktree. */
  isolate?: boolean
}

export type StipClientSettings = {
  defaults?: StipProfile & { max_workers?: number; max_shared_writers?: number }
  roles?: Record<string, StipProfile>
  phases?: Record<string, StipProfile>
  phase_roles?: Record<string, Record<string, StipProfile>>
  enforcement?: { apply_gate?: StipApplyGate }
}

export type StipScope = 'personal' | 'project' | 'local'

/** Effective claude-code settings after personal <- project <- local. */
export type StipEffectiveSettings = {
  client: StipClientSettings
  limits: { max_workers: number; max_shared_writers: number }
  applyGate: StipApplyGate
}

export type StipSettingsView = {
  effective: StipEffectiveSettings
  /** Each scope's orchestration.clients["claude-code"] section as stored. */
  byScope: Record<StipScope, StipClientSettings>
  /** Paths of the three scope files. */
  paths: Record<StipScope, string>
  /** Optimistic revision over the three scope files; pass it back to saveSettings. */
  revision: string
  error: string | null
}

/** What the core records for a spawned agent, keyed by agent id. */
export type StipBinding = {
  agentId: string
  kind: 'task' | 'helper'
  changeId: string | null
  taskId: string
  attempt: number
  helperId: string | null
  /** Absolute working directory (worktree when isolated, else project root). */
  cwd: string
  writePaths: string[]
  status: StipJobStatus
  startedAt: number
  lastTool: string | null
}

/**
 * The interface's actions, run through the core with
 *   $.command.run({ command: 'stip-action', args: JSON.stringify(action) })
 * (a `$` cannot cross module files). The command answers `{ text }` holding
 * StipActionReply as JSON; the snapshot and settings state update on their own.
 */
export type StipAction =
  | { action: 'refresh' }
  | { action: 'bind'; change_id: string }
  | { action: 'accept'; change_id: string; task_id: string; reason: string }
  | { action: 'reject'; change_id: string; task_id: string; reason: string; discard?: boolean }
  | { action: 'cancel'; change_id: string; task_id: string; reason?: string }
  | { action: 'cancel'; helper_id: string; reason?: string }
  | { action: 'delegate'; change_id: string; task_id: string; instructions?: string; correction?: boolean }
  | { action: 'approve'; change_id: string; digest: string }
  | { action: 'rebase'; change_id: string }
  | { action: 'result'; change_id: string; task_id: string; attempt?: number }
  | { action: 'result'; helper_id: string }
  | { action: 'settings-load' }
  | { action: 'settings-save'; scope: StipScope; value: StipClientSettings; revision: string }

export type StipActionReply =
  | { ok: true; action: StipAction['action']; value: unknown }
  | { ok: false; error: string; conflicts?: { path: string; reason: string }[] }

/**
 * A reserved launch: stip_delegate / stip_research reserve through the engine and hand the
 * coordinator model this ticket; the model launches it with the Agent tool (so the worker's own
 * tool calls reach the mod's guards) and the mod's agent.spawn hook fills in the brief, working
 * directory and background mode, then confirms the real agent id. Keyed by `description`.
 */
export type StipTicket = {
  description: string
  kind: 'task' | 'helper'
  changeId: string | null
  taskId: string
  attempt: number
  helperId: string | null
  subagentType: string
  prompt: string
  /** Worktree when isolated; null runs in the session's directory. */
  cwd: string | null
  model: string | null
  writePaths: string[]
  createdAt: number
}

declare module 'claude-code' {
  interface PluginState {
    stipulate: {
      snapshot: StipSnapshot | null
      settings: StipSettingsView | null
      /** The change bound to this session. */
      binding: string | null
      /** Agent id -> worker binding; survives hot reload. */
      workers: Record<string, StipBinding>
      /** Tampered attempts by `<change>/<task>#<attempt>`, until the attempt is reviewed. */
      tampered: Record<string, StipTamper>
      /** Reserved launches waiting for the coordinator's Agent call, by description. */
      tickets: Record<string, StipTicket>
      /** UI: the band is hidden by the person. */
      bandHidden: boolean
      /** UI: the task selected in the pane. */
      selectedTask: string | null
      /** UI: the settings pane's unsaved edit. */
      settingsDraft: unknown
    }
  }
}
